-- Safe realtime activity signal for Active today. Applied to production Supabase on 2026-10-26.
create table if not exists public.member_activity(user_id uuid primary key references public.profiles(id) on delete cascade,activity_date date not null,last_activity_at timestamptz not null);
alter table public.member_activity enable row level security;
create policy "member_activity: shared group read" on public.member_activity for select to authenticated using(user_id=(select auth.uid()) or(exists(select 1 from public.profiles p where p.id=user_id and p.show_active_today)and exists(select 1 from public.group_members mine join public.group_members theirs on theirs.group_id=mine.group_id where mine.user_id=(select auth.uid())and theirs.user_id=member_activity.user_id)));
grant select on public.member_activity to authenticated;
create or replace function private.touch_member_activity() returns trigger language plpgsql security definer set search_path='' as $$
declare v_user uuid;v_date date;v_at timestamptz;begin if tg_table_name='daily_steps' then if coalesce(new.steps,0)<=0 then return new;end if;v_user:=new.user_id;v_date:=new.step_date;v_at:=coalesce(new.synced_at,now());elsif tg_table_name='protein_logs' then if coalesce(new.grams,0)<=0 then return new;end if;v_user:=new.user_id;v_date:=new.log_date;v_at:=coalesce(new.logged_at,now());else return new;end if;insert into public.member_activity(user_id,activity_date,last_activity_at)values(v_user,v_date,v_at)on conflict(user_id)do update set activity_date=excluded.activity_date,last_activity_at=greatest(public.member_activity.last_activity_at,excluded.last_activity_at)where excluded.activity_date>public.member_activity.activity_date or(excluded.activity_date=public.member_activity.activity_date and excluded.last_activity_at>public.member_activity.last_activity_at);return new;end$$;
drop trigger if exists trg_daily_steps_member_activity on public.daily_steps;create trigger trg_daily_steps_member_activity after insert or update of steps,synced_at on public.daily_steps for each row execute function private.touch_member_activity();
drop trigger if exists trg_protein_logs_member_activity on public.protein_logs;create trigger trg_protein_logs_member_activity after insert or update of grams,logged_at on public.protein_logs for each row execute function private.touch_member_activity();
insert into public.member_activity(user_id,activity_date,last_activity_at) select x.user_id,x.activity_date,max(x.at)from(select user_id,step_date activity_date,synced_at at from public.daily_steps where steps>0 union all select user_id,log_date,logged_at from public.protein_logs where grams>0)x join(select user_id,max(activity_date)d from(select user_id,step_date activity_date from public.daily_steps where steps>0 union all select user_id,log_date from public.protein_logs where grams>0)z group by user_id)latest on latest.user_id=x.user_id and latest.d=x.activity_date group by x.user_id,x.activity_date on conflict(user_id)do update set activity_date=excluded.activity_date,last_activity_at=excluded.last_activity_at;
create or replace function public.get_active_today(p_local_date date) returns table(user_id uuid,display_name text,avatar_url text,streak integer,last_activity timestamptz,group_id uuid) language sql stable security definer set search_path='' as $$
with viewer_groups as(select gm.group_id from public.group_members gm where gm.user_id=(select auth.uid())),shared as(select gm.user_id,gm.group_id,count(*)over(partition by gm.group_id)group_size from public.group_members gm join viewer_groups vg on vg.group_id=gm.group_id),candidates as(select distinct on(s.user_id)s.user_id,s.group_id from shared s join public.profiles p on p.id=s.user_id where(p.show_active_today or p.id=(select auth.uid()))order by s.user_id,s.group_size desc,s.group_id)select p.id,p.display_name,p.avatar_url,case when p.id=(select auth.uid())or p.show_group_steps then greatest(coalesce(p.step_streak,p.streak,0),0)else null end,ma.last_activity_at,c.group_id from candidates c join public.profiles p on p.id=c.user_id join public.member_activity ma on ma.user_id=p.id and ma.activity_date=p_local_date order by(p.id=(select auth.uid()))desc,ma.last_activity_at desc limit 20;$$;
revoke all on function private.touch_member_activity() from public,anon,authenticated;
do $$begin alter publication supabase_realtime add table public.member_activity;exception when duplicate_object then null;end$$;
